long long count_pairs(int n) {
    long long count = 0;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j <= i; ++j) ++count;
    return count;
}
int halvings(int n) {
    int steps = 0;
    while (n > 1) { n /= 2; ++steps; }
    return steps;
}

