vector<long long> prefix(const vector<long long>& a) {
    vector<long long> p(a.size() + 1, 0);
    for (int i = 0; i < (int)a.size(); ++i) p[i+1] = p[i] + a[i];
    return p;
}
vector<long long> apply_updates(int n,
        const vector<tuple<int,int,long long>>& updates) {
    vector<long long> d(n+1, 0), a(n);
    for (auto [l,r,x] : updates) {
        assert(0 <= l && l <= r && r <= n);
        d[l] += x; d[r] -= x;
    }
    long long current = 0;
    for (int i = 0; i < n; ++i) { current += d[i]; a[i] = current; }
    return a;
}

