long long count_subarrays(const vector<long long>& a, long long k) {
    if (k < 0) return 0;
    long long sum = 0, answer = 0;
    int l = 0;
    for (int r = 0; r < (int)a.size(); ++r) {
        assert(a[r] >= 0);
        sum += a[r];
        while (sum > k) sum -= a[l++];
        answer += r-l+1;
    }
    return answer;
}

