pair<vector<int>,vector<int>> bfs(const vector<vector<int>>& g, int s) {
    int n = g.size();
    assert(0 <= s && s < n);
    vector<int> dist(n,-1), parent(n,-1);
    queue<int> q; q.push(s); dist[s]=0;
    while (!q.empty()) {
        int v=q.front(); q.pop();
        for (int u:g[v]) if (dist[u]==-1) {
            dist[u]=dist[v]+1; parent[u]=v; q.push(u);
        }
    }
    return {dist,parent};
}

#include <bits/stdc++.h>
