vector<int> components(const vector<vector<int>>& g) {
    int n=g.size(), count=0;
    vector<int> comp(n,-1);
    for (int s=0;s<n;++s) if (comp[s]==-1) {
        vector<int> st={s}; comp[s]=count;
        while (!st.empty()) {
            int v=st.back(); st.pop_back();
            for (int u:g[v]) if (comp[u]==-1) {
                comp[u]=count; st.push_back(u);
            }
        }
        ++count;
    }
    return comp;
}

