struct SegTree {
    int n,size=1;vector<long long> t;
    SegTree(const vector<long long>& a):n(a.size()){
        while(size<n)size*=2;t.assign(2*size,0);
        for(int i=0;i<n;i++)t[size+i]=a[i];
        for(int i=size-1;i>0;i--)t[i]=t[2*i]+t[2*i+1];
    }
    void assign(int i,long long x){
        assert(0<=i&&i<n);i+=size;t[i]=x;
        for(i/=2;i>0;i/=2)t[i]=t[2*i]+t[2*i+1];
    }
    long long sum(int l,int r)const{
        assert(0<=l&&l<=r&&r<=n);long long answer=0;
        for(l+=size,r+=size;l<r;l/=2,r/=2){
            if(l&1)answer+=t[l++];if(r&1)answer+=t[--r];
        }
        return answer;
    }
};

