struct SparseTable {
    vector<vector<long long>> st;vector<int> lg;int n;
    SparseTable(const vector<long long>& a):n(a.size()){
        assert(n>0);lg.assign(n+1,0);
        for(int i=2;i<=n;i++)lg[i]=lg[i/2]+1;
        st.assign(lg[n]+1,vector<long long>(n));st[0]=a;
        for(int k=1;k<(int)st.size();k++)
            for(int i=0;i+(1<<k)<=n;i++)
                st[k][i]=min(st[k-1][i],st[k-1][i+(1<<(k-1))]);
    }
    long long query(int l,int r)const{
        assert(0<=l&&l<r&&r<=n);int k=lg[r-l];
        return min(st[k][l],st[k][r-(1<<k)]);
    }
};

