const long long INF=4'000'000'000'000'000'000LL;
vector<long long> dijkstra(const vector<vector<pair<int,long long>>>& g,int s){
    int n=g.size();assert(0<=s&&s<n);
    vector<long long>d(n,INF);d[s]=0;
    priority_queue<pair<long long,int>,vector<pair<long long,int>>,
                   greater<pair<long long,int>>>q;q.push({0,s});
    while(!q.empty()){
        auto [dv,v]=q.top();q.pop();if(dv!=d[v])continue;
        for(auto [u,w]:g[v]){
            assert(w>=0 && w<INF);
            if(dv<=INF-w && dv+w<d[u]){
                d[u]=dv+w;q.push({d[u],u});
            }
        }
    }
    return d;
}

