optional<vector<int>> topological(const vector<vector<int>>& g){
    int n=g.size();vector<int>deg(n),order;queue<int>q;
    for(auto&edges:g)for(int u:edges)++deg[u];
    for(int v=0;v<n;v++)if(!deg[v])q.push(v);
    while(!q.empty()){
        int v=q.front();q.pop();order.push_back(v);
        for(int u:g[v])if(--deg[u]==0)q.push(u);
    }
    if((int)order.size()!=n)return nullopt;
    return order;
}

