long long stair_ways(int n){
    assert(n>=0);const long long MOD=1'000'000'007;
    if(n==0)return 1;
    long long previous=1,current=1;
    for(int i=2;i<=n;i++){
        long long next=(previous+current)%MOD;
        previous=current;current=next;
    }
    return current;
}

