long long knapsack(int W,const vector<pair<int,long long>>& items){
    assert(W>=0);vector<long long>dp(W+1,0);
    for(auto [w,v]:items){
        assert(w>0);
        for(int c=W;c>=w;c--)dp[c]=max(dp[c],dp[c-w]+v);
    }
    return dp[W];
}

