struct LCA {
    int n,LOG=1;vector<int>depth;vector<vector<int>>up;
    LCA(const vector<vector<int>>&g,int root):n(g.size()),depth(n,-1){
        assert(n>0&&0<=root&&root<n);
        while((1LL<<LOG)<=n)++LOG;up.assign(LOG,vector<int>(n,root));
        queue<int>q;depth[root]=0;q.push(root);
        while(!q.empty()){
            int v=q.front();q.pop();
            for(int u:g[v])if(depth[u]==-1){
                depth[u]=depth[v]+1;up[0][u]=v;q.push(u);
            }
        }
        for(int d:depth)assert(d!=-1);
        for(int k=1;k<LOG;k++)for(int v=0;v<n;v++)
            up[k][v]=up[k-1][up[k-1][v]];
    }
    int query(int a,int b)const{
        if(depth[a]<depth[b])swap(a,b);
        int diff=depth[a]-depth[b];
        for(int k=0;k<LOG;k++)if(diff>>k&1)a=up[k][a];
        if(a==b)return a;
        for(int k=LOG-1;k>=0;k--)if(up[k][a]!=up[k][b]){
            a=up[k][a];b=up[k][b];
        }
        return up[0][a];
    }
    int distance(int a,int b)const{return depth[a]+depth[b]-2*depth[query(a,b)];}
};

