vector<int> prefix_function(const string& p){
    vector<int>pi(p.size());
    for(int i=1;i<(int)p.size();i++){
        int j=pi[i-1];
        while(j>0&&p[i]!=p[j])j=pi[j-1];
        if(p[i]==p[j])++j;pi[i]=j;
    }
    return pi;
}
vector<int> kmp(const string& text,const string& pattern){
    int n=text.size(),m=pattern.size();vector<int>answer;
    if(m==0){answer.resize(n+1);iota(answer.begin(),answer.end(),0);return answer;}
    auto pi=prefix_function(pattern);int j=0;
    for(int i=0;i<n;i++){
        while(j>0&&text[i]!=pattern[j])j=pi[j-1];
        if(text[i]==pattern[j])++j;
        if(j==m){answer.push_back(i-m+1);j=pi[j-1];}
    }
    return answer;
}

