vector<bool> sieve(int n){
    assert(n>=0);vector<bool>prime(n+1,true);
    prime[0]=false;if(n>=1)prime[1]=false;
    for(int p=2;1LL*p*p<=n;p++)if(prime[p])
        for(long long x=1LL*p*p;x<=n;x+=p)prime[x]=false;
    return prime;
}
long long modpow(long long a,long long e,long long m){
    assert(e>=0&&m>0);a%=m;if(a<0)a+=m;long long r=1%m;
    while(e){
        if(e&1)r=(__int128)r*a%m;
        a=(__int128)a*a%m;e/=2;
    }
    return r;
}

