struct Combinations{
    static constexpr long long MOD=1'000'000'007;
    vector<long long>f,invf;
    static long long power(long long a,long long e){
        long long r=1;while(e){if(e&1)r=r*a%MOD;a=a*a%MOD;e/=2;}return r;
    }
    Combinations(int n):f(n+1,1),invf(n+1,1){
        assert(0<=n&&n<MOD);
        for(int i=1;i<=n;i++)f[i]=f[i-1]*i%MOD;
        invf[n]=power(f[n],MOD-2);
        for(int i=n;i>0;i--)invf[i-1]=invf[i]*i%MOD;
    }
    long long choose(int n,int k)const{
        assert(0<=n&&n<(int)f.size());
        if(k<0||k>n)return 0;
        return f[n]*invf[k]%MOD*invf[n-k]%MOD;
    }
};

#include <bits/stdc++.h>
using namespace std;

long long assignment(const vector<vector<long long>>& cost){
    int n=cost.size();assert(n<=20);
    for(auto&r:cost)assert((int)r.size()==n);
    const long long INF=4'000'000'000'000'000'000LL;
    int states=1<<n;vector<long long>dp(states,INF);dp[0]=0;
    for(int mask=0;mask<states;mask++){
        int i=__builtin_popcount((unsigned)mask);if(i==n)continue;
        for(int j=0;j<n;j++)if(!(mask>>j&1)){
            assert(cost[i][j]>=0&&cost[i][j]<INF/20);
            int next=mask|(1<<j);
            dp[next]=min(dp[next],dp[mask]+cost[i][j]);
        }
    }
    return dp.back();
}

#include <bits/stdc++.h>
using namespace std;

struct LazySeg{
    int n;vector<long long>sum,lazy;
    LazySeg(const vector<long long>&a):n(a.size()),sum(4*n),lazy(4*n){
        assert(n>0);build(1,0,n,a);
    }
    void build(int v,int l,int r,const vector<long long>&a){
        if(r-l==1){sum[v]=a[l];return;}int m=(l+r)/2;
        build(v*2,l,m,a);build(v*2+1,m,r,a);sum[v]=sum[v*2]+sum[v*2+1];
    }
    void apply(int v,int l,int r,long long x){sum[v]+=x*(r-l);lazy[v]+=x;}
    void push(int v,int l,int r){
        if(r-l==1||lazy[v]==0)return;int m=(l+r)/2;
        apply(v*2,l,m,lazy[v]);apply(v*2+1,m,r,lazy[v]);lazy[v]=0;
    }
    void add(int ql,int qr,long long x,int v,int l,int r){
        if(qr<=l||r<=ql)return;
        if(ql<=l&&r<=qr){apply(v,l,r,x);return;}
        push(v,l,r);int m=(l+r)/2;
        add(ql,qr,x,v*2,l,m);add(ql,qr,x,v*2+1,m,r);
        sum[v]=sum[v*2]+sum[v*2+1];
    }
    long long query(int ql,int qr,int v,int l,int r){
        if(qr<=l||r<=ql)return 0;if(ql<=l&&r<=qr)return sum[v];
        push(v,l,r);int m=(l+r)/2;
        return query(ql,qr,v*2,l,m)+query(ql,qr,v*2+1,m,r);
    }
    void add(int l,int r,long long x){assert(0<=l&&l<=r&&r<=n);add(l,r,x,1,0,n);}
    long long query(int l,int r){assert(0<=l&&l<=r&&r<=n);return query(l,r,1,0,n);}
};
